import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	_ "embed"
	"encoding/base64"
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/deluan/rest"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/consts"
	"github.com/navidrome/navidrome/core/auth"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
	"github.com/navidrome/navidrome/server"
	"github.com/navidrome/navidrome/utils"
)

//go:embed token_received.html
var tokenReceivedPage []byte

type Router struct {
	http.Handler
	ds          model.DataStore
	sessionKeys *sessionKeys
	client      *Client
	apiKey      string
	secret      string
	stateSecret []byte
}

func NewRouter(ds model.DataStore) *Router {
	r := &Router{
		ds:          ds,
		apiKey:      conf.Server.LastFM.ApiKey,
		secret:      conf.Server.LastFM.Secret,
		sessionKeys: &sessionKeys{ds: ds},
	}
	r.Handler = r.routes()
	hc := &http.Client{
		Timeout: consts.DefaultHttpClientTimeOut,
	}
	r.client = NewClient(r.apiKey, r.secret, "en", hc)
	return r
}

func (s *Router) routes() http.Handler {
	r := chi.NewRouter()

	r.Group(func(r chi.Router) {
		r.Use(server.Authenticator(s.ds))
		r.Use(server.JWTRefresher)

		r.Get("/link", s.getLinkStatus)
		r.Get("/link/state", s.getLinkState)
		r.Delete("/link", s.unlink)
	})

	r.Get("/link/callback", s.callback)

	return r
}

type linkState struct {
	UserID  string `json:"userId"`
	Expires int64  `json:"expires"`
}

func (s *Router) linkStateSecret() []byte {
	if s.stateSecret != nil {
		return s.stateSecret
	}
	return auth.Secret
}

func (s *Router) signLinkState(userId string) string {
	payload, _ := json.Marshal(linkState{UserID: userId, Expires: time.Now().Add(10 * time.Minute).Unix()})
	mac := hmac.New(sha256.New, s.linkStateSecret())
	_, _ = mac.Write(payload)
	return base64.RawURLEncoding.EncodeToString(payload) + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func (s *Router) parseLinkState(value string) (string, error) {
	parts := bytes.Split([]byte(value), []byte("."))
	if len(parts) != 2 {
		return "", errors.New("invalid link state")
	}
	if len(s.linkStateSecret()) == 0 {
		return "", errors.New("link state unavailable")
	}
	payload, err := base64.RawURLEncoding.DecodeString(string(parts[0]))
	if err != nil {
		return "", errors.New("invalid link state")
	}
	signature, err := base64.RawURLEncoding.DecodeString(string(parts[1]))
	if err != nil {
		return "", errors.New("invalid link state")
	}
	mac := hmac.New(sha256.New, s.linkStateSecret())
	_, _ = mac.Write(payload)
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return "", errors.New("invalid link state")
	}
	var state linkState
	if json.Unmarshal(payload, &state) != nil || state.UserID == "" || time.Now().Unix() >= state.Expires {
		return "", errors.New("invalid link state")
	}
	return state.UserID, nil
}

func (s *Router) getLinkState(w http.ResponseWriter, r *http.Request) {
	user, ok := request.UserFrom(r.Context())
	if !ok {
		_ = rest.RespondWithError(w, http.StatusUnauthorized, "user not authenticated")
		return
	}
	if len(s.linkStateSecret()) == 0 {
		_ = rest.RespondWithError(w, http.StatusInternalServerError, "link state unavailable")
		return
	}
	_ = rest.RespondWithJSON(w, http.StatusOK, map[string]string{"state": s.signLinkState(user.ID)})
package server

import (
	"context"
	"fmt"
	"os/exec"
	"time"

	"github.com/google/uuid"
	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/consts"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
)

func initialSetup(ds model.DataStore) {
	_ = ds.WithTx(func(tx model.DataStore) error {
		properties := ds.Property(context.TODO())
		_, err := properties.Get(consts.InitialSetupFlagKey)
		if err == nil {
			return nil
		}
		log.Info("Running initial setup")
		if err = createJWTSecret(ds); err != nil {
			return err
		}

		if conf.Server.DevAutoCreateAdminPassword != "" {
			if err = createInitialAdminUser(ds, conf.Server.DevAutoCreateAdminPassword); err != nil {
				return err
			}
		}

		err = properties.Put(consts.InitialSetupFlagKey, time.Now().String())
		return err
	})
}

func createInitialAdminUser(ds model.DataStore, initialPassword string) error {
	users := ds.User(context.TODO())
	c, err := users.CountAll()
	if err != nil {
		panic(fmt.Sprintf("Could not access User table: %s", err))
	}
	if c == 0 {
		id := uuid.NewString()
		log.Warn("Creating initial admin user. This should only be used for development purposes!!",
			"user", consts.DevInitialUserName, "password", initialPassword, "id", id)
		initialUser := model.User{
			ID:          id,
			UserName:    consts.DevInitialUserName,
			Name:        consts.DevInitialName,
			Email:       "",
			NewPassword: initialPassword,
			IsAdmin:     true,
		}
		err := users.Put(&initialUser)
		if err != nil {
			log.Error("Could not create initial admin user", "user", initialUser, err)
		}
	}
	return err
}

func createJWTSecret(ds model.DataStore) error {
	properties := ds.Property(context.TODO())
	_, err := properties.Get(consts.JWTSecretKey)
	if err == nil {
		return nil
	}
	log.Info("Creating new JWT secret, used for encrypting UI sessions")
	err = properties.Put(consts.JWTSecretKey, uuid.NewString())
	if err != nil {
		log.Error("Could not save JWT secret in DB", err)
	}
	return err
}

func checkFfmpegInstallation() {
	path, err := exec.LookPath("ffmpeg")
	if err == nil {
		log.Info("Found ffmpeg", "path", path)
		return
	}
	log.Warn("Unable to find ffmpeg. Transcoding will fail if used", err)
	if conf.Server.Scanner.Extractor == "ffmpeg" {
		log.Warn("ffmpeg cannot be used for metadata extraction. Falling back to taglib")
		conf.Server.Scanner.Extractor = "taglib"
	}
}

func checkExternalCredentials() {
	if !conf.Server.LastFM.Enabled {
		log.Info("Last.FM integration is DISABLED")
	} else {
		log.Debug("Last.FM integration is ENABLED")
	}

	if conf.Server.Spotify.ID == "" || conf.Server.Spotify.Secret == "" {
		log.Info("Spotify integration is not enabled: missing ID/Secret")
	} else {
		log.Debug("Spotify integration is ENABLED")
	}
}

